/** @type {Handler} */
export const handler = async (input) => {
  const glucosaValida = typeof input.glucosa_ayunas === 'number' && input.glucosa_ayunas > 0;
  const insulinaValida = typeof input.insulina_ayunas === 'number' && input.insulina_ayunas > 0;

  let homaIr = typeof input.homa_ir === 'number' ? input.homa_ir : null;
  if (homaIr === null && glucosaValida && insulinaValida) {
    homaIr = (input.glucosa_ayunas * input.insulina_ayunas) / 405;
  }

  let quicki = typeof input.quicki === 'number' ? input.quicki : null;
  if (quicki === null && glucosaValida && insulinaValida) {
    const denominador = Math.log10(input.glucosa_ayunas) + Math.log10(input.insulina_ayunas);
    if (denominador > 0) quicki = 1 / denominador;
  }

  const resistenciaConfirmada = homaIr !== null && homaIr >= 2.5;
  let gradoResistencia = 'no_confirmada';
  if (homaIr !== null && homaIr >= 5.0) gradoResistencia = 'severa';
  else if (homaIr !== null && homaIr >= 3.0) gradoResistencia = 'moderada';
  else if (homaIr !== null && homaIr >= 2.5) gradoResistencia = 'leve';

  const hba1cAlta = typeof input.hemoglobina_glicosilada === 'number' && input.hemoglobina_glicosilada >= 5.7;
  const glucosaAlta = glucosaValida && input.glucosa_ayunas >= 100;
  let riesgoDiabetes = 'bajo';
  if (hba1cAlta || glucosaAlta) riesgoDiabetes = 'alto';
  else if (resistenciaConfirmada) riesgoDiabetes = 'moderado';

  const trigliceridosAltos = typeof input.trigliceridos === 'number' && input.trigliceridos >= 150;
  const hdlBajo = typeof input.hdl === 'number' && input.hdl < 50;
  let riesgoCardiometabolico = 'bajo';
  if (trigliceridosAltos && hdlBajo) riesgoCardiometabolico = 'alto';
  else if (trigliceridosAltos || hdlBajo) riesgoCardiometabolico = 'moderado';

  const conclusion = resistenciaConfirmada
    ? `Compatible con resistencia a la insulina ${gradoResistencia}`
    : 'No compatible con resistencia a la insulina';

  return {
    homa_ir: homaIr,
    quicki,
    resistencia_confirmada: resistenciaConfirmada,
    grado_resistencia: gradoResistencia,
    riesgo_diabetes: riesgoDiabetes,
    riesgo_cardiometabolico: riesgoCardiometabolico,
    conclusion,
    acantosis_nigricans: input.acantosis_nigricans === true,
    obesidad_abdominal: input.obesidad_abdominal === true
  };
};
